CREATE TABLE "true_up_actions" (
	"id" bigint PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "true_up_actions_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START WITH 1 CACHE 1),
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"run_id" bigint,
	"mba_number" text NOT NULL,
	"component" text NOT NULL,
	"action" text NOT NULL,
	"strategy" text,
	"months" text[] DEFAULT '{}'::text[] NOT NULL,
	"as_of_month" date NOT NULL,
	"gap_cents" bigint NOT NULL,
	"amount_cents" bigint DEFAULT 0 NOT NULL,
	"billing_revision_id" bigint,
	"reason_code" text,
	"note" text,
	"xero_invoice_id" text,
	"status" text DEFAULT 'applied' NOT NULL,
	"created_by" bigint NOT NULL,
	"created_by_name" text,
	"undone_at" timestamp with time zone,
	"undone_by" bigint,
	"preview_hash" text,
	CONSTRAINT "true_up_actions_component_check" CHECK ("true_up_actions"."component" IN ('fee', 'adserving', 'production', 'media')),
