	CONSTRAINT "true_up_actions_strategy_check" CHECK ("true_up_actions"."strategy" IS NULL OR "true_up_actions"."strategy" IN ('spread', 'carry')),
	CONSTRAINT "true_up_actions_reason_check" CHECK ("true_up_actions"."reason_code" IS NULL OR "true_up_actions"."reason_code" IN ('timing', 'prebill', 'client_agreed', 'schedule_incomplete', 'other')),
	CONSTRAINT "true_up_actions_status_check" CHECK ("true_up_actions"."status" IN ('applied', 'undone')),
	CONSTRAINT "true_up_actions_mba_check" CHECK (length(btrim("true_up_actions"."mba_number")) > 0)
);
