CREATE TABLE "true_up_invoice_links" (
	"id" bigint PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "true_up_invoice_links_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START WITH 1 CACHE 1),
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"xero_invoice_id" text NOT NULL,
	"mba_number" text NOT NULL,
	"billing_month" date,
	"note" text,
	"created_by" bigint NOT NULL,
	"created_by_name" text,
	CONSTRAINT "true_up_invoice_links_mba_check" CHECK (length(btrim("true_up_invoice_links"."mba_number")) > 0),
	CONSTRAINT "true_up_invoice_links_month_check" CHECK ("true_up_invoice_links"."billing_month" IS NULL OR "true_up_invoice_links"."billing_month" = date_trunc('month', "true_up_invoice_links"."billing_month")::date)
);
